head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDSTF05710";
scwin.openTyp = "";         // 여는 방식 R: 접수, H: 이력, N: 신규
scwin.bzProcsNo = "";       // 업무처리번호 (R: 접수 행, H: 목록 행, N: "") — 신규 저장 성공 뒤 확정
scwin.acptNo = "";          // 접수번호 (R 만) — 있으면 저장 때 채번하지 않는다
scwin.isurCd = "";          // 발행회사코드
scwin.secugrpId = "";       // 증권그룹ID (SW)
scwin.mktTpCd = "";         // 시장구분 1: 유가, 2: 코스닥
scwin.recv = null;          // 접수 목록 선택 행 (R 만)
scwin.trJob = "";           // 처리구분 I: 저장, U: 수정, D: 삭제
scwin.detailRow = {};       // 상세 조회에서 찾은 원본 행 전체 — 공시안내문 mst 로 넘긴다(원본 CopyDataSet(dts_Isu), §6.5)
scwin.DSCL_FORM_CD_KSE = "68912";       // 공시안내문 서식코드 — 유가
scwin.DSCL_FORM_CD_KOSDAQ = "70920";    // 공시안내문 서식코드 — 코스닥
scwin.REPORT_ID = "RLDSTF00029";        // 증권발행내역 리포트
scwin.COMPLETE_YN_OK = "Y";             // 저장·삭제 응답 completeYn 의 성공 값 — TODO: 명세에 값이 없어 가정 (§10 #7)
// 원본 : /lstproc/ULDSTF05710.gfm (신주인수권증권 신주상장관리 팝업)
/*
 * 화면 동작
 *  - 부모(ULDSTF05700)가 넘긴 openTyp 로 모드가 정해진다 — N 신규, R 접수(접수 행 값을 미리 채움), H 이력(업무처리번호로 상세 조회).
 *  - 신규·접수는 [종목 찾기](ULDSTF92016)로 종목을 고르고 필수 항목을 입력해 저장한다(검증 → 확인 → 채번 → 등록).
 *  - 수정 모드는 상장일이 지나지 않았거나 공시되지 않은 건만 [수정]·[삭제]·[안내문작성] 할 수 있다.
 *  - 저장·수정·삭제는 명세대로 ref : "dma_detail" 로 보낸다. 삭제에 성공하면 팝업을 닫고, 부모는 await 가 끝나면 목록을 다시 조회한다.
 *  - 공시안내문작성(ULDSTF92024)은 openPopup 의 data 로 넘기고 await 한다.
 *    92024 전환본이 아직 부모 getPar 를 부르므로 호환용 scwin.getPar 만 임시로 둔다(§10 #8).
 * 업무 분석 : conversion/gfm-front/ui/ULDSTF05710/ULDSTF05710.md (§번호는 이 문서의 절)
 */

// 부모 화면에서 넘겨받는 값 (§1.2)

// 화면 상태값

// 고정값

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
// [신청종목삭제]·[인쇄]는 원본 buttonSet 밖의 버튼이라 따로 다룬다(§4).
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update",      // [수정]
    "delete" : "btn_Delete",    // [삭제]
    guide : "btn_Dscl"          // [안내문작성]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 27
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05710.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 27
 * @description 로딩 — 버튼 잠금 → 파라미터 수신 → 승인일 기본값 → 달력 바인딩 → 인쇄 표시 → 모드 분기(N·R 신규 준비 / H 상세 조회). (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 로딩 동안 버튼 잠금 — 조회가 예외로 끝나도 버튼이 XML 기본값(전부 활성)으로 남지 않게 한다.
    $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
    btn_RecvIsuDel.setDisabled(true);

    // 2) 파라미터 수신 — 원본 frame.Provider("../") 의 부모 전역 직접 참조 (§1.2)
    // TODO: 키 이름은 부모 ULDSTF05700 전환 전 제안값 (§10 #6)
    const param = $c.data.getParameter() ?? {};

    scwin.openTyp = String(param.openTyp ?? "");                       // AS-IS vOpenTyp
    scwin.bzProcsNo = String(param.bzProcsNo ?? "");                   // AS-IS clickBzProcsNo
    scwin.acptNo = String(param.acptNo ?? "");                         // AS-IS vAcptNo
    scwin.isurCd = String(param.isurCd ?? "");                         // AS-IS txb_ISUR_CD
    scwin.secugrpId = String(param.secugrpId ?? "");                   // AS-IS pSecuGrpId
    scwin.mktTpCd = String(param.spotIsuTrdMktTpCd ?? "");             // AS-IS vSPOT_ISU_TRD_MKT_TP_CD
    scwin.recv = param.recv ?? null;                                   // AS-IS dts_Recv 선택 행

    // 승인일(인쇄용) 기본값 — 서버 현재일 (원본 cGetToday)
    edt_APPROV_DD.setValue($c.date.getServerDateTime().substring(0, 8));

    // 3) 달력 검사 바인딩(1회) — 단일 달력은 checkCalendarFormat, 기간 쌍은 compareFromToDate 만(규칙 37)
    $c.date.checkCalendarFormat(edt_ISU_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_LIST_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_APPROV_DD, "yyyyMMdd");
    $c.date.compareFromToDate(edt_EXER_STRT_DD, edt_EXER_END_DD, ["행사시작일", "행사종료일"]);

    // 4) 인쇄 표시 — 파라미터만 보므로 모드 분기 앞에 둔다(상세 조회가 예외로 끝나도 유가에서 [인쇄]·승인일이 보이지 않게).
    scwin.setPrintVisible();

    // 5) 모드 분기 — R/H/N 이 아니면 원본처럼 아무것도 하지 않는다(버튼은 잠긴 채)
    if (scwin.openTyp === "H") {
        await scwin.selectDetail();
    } else if (scwin.openTyp === "R" || scwin.openTyp === "N") {
        scwin.initNewForm();
        if (scwin.openTyp === "R") scwin.applyRecv(scwin.recv);
        $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
        scwin.setBtnRecvIsuDel();
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.img_ISU_CD_onclick
 * @author Inswave
 * @date 2026. 10. 27
 * @description 종목 찾기(돋보기) 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_ISU_CD_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05710.img_ISU_CD_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Save_onclick
 * @author Inswave
 * @date 2026. 10. 27
 * @description 저장 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05710.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Update_onclick
