///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectDetail
 * @author Inswave
 * @date 2026. 10. 27
 * @description 상세 조회. 회사의 신주상장 내역을 받아 업무처리번호 행을 상세에 옮기고 버튼 상태를 정한다.
 * (원본 fn_read_sync 동기 2회 → 1회, dts_Isu OnLoadCompleted — §5.1, §6.11, §6.12)
 * @returns {Promise<Boolean>} 상세를 채웠으면 true
 * @hidden N
 */
scwin.selectDetail = async function () {
    const sbmOptions = {
        id : "sbm_selectDetail",
        method : "get",
        action : "/api/listing/lstproc/warrant/listing/select-list-hist",
        target : "dlt_list=body",
        isProcessMsg : false
    };

    // TODO: 상세 전용 API 가 없어 회사 전체 이력에서 bzProcsNo 행을 고른다 — bzProcsNo 조건 추가 여부 확인 (§10 #5)
    const result = await $c.sbm.executeDynamic(sbmOptions, { isurCd : scwin.isurCd, secugrpId : scwin.secugrpId });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    // 실패하거나 해당 행이 없으면 버튼을 모두 잠근다 — 저장 뒤 재조회 실패에서
    // 신규 상태(insert, [저장] 활성)가 남아 같은 건을 다시 저장하지 않게 한다.
    if (!result.responseJSON?.success || !scwin.setDetailFromList()) {
        $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
        btn_RecvIsuDel.setDisabled(true);
        // TODO: 가정 문구 (§10 #14)
        await $c.win.alert("상세 내역을 찾을 수 없습니다.");
        return false;
    }

    scwin.applyButtonState();
    scwin.setBtnRecvIsuDel();
    return true;
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 27
 * @description 신규 저장(I)·수정(U). dma_detail 을 ref 로 보내고, 성공하면 상세를 다시 조회해 수정 모드로 둔다.
 * (원본 fn_trs + trs_Save OnSuccess/OnFail — §5.5, §5.6)
 * @param {String} trJob 처리구분 I: 저장, U: 수정
 * @returns
 * @hidden N
 */
scwin.saveTrs = async function (trJob) {
    const jobNm = (trJob === "I") ? "저장" : "수정";

    const sbmOptions = {
        id : "sbm_saveTrs",
        method : "post",
        action : (trJob === "I") ? "/api/listing/lstproc/warrant/listing/register" : "/api/listing/lstproc/warrant/listing/modify",
        ref : "dma_detail",
        target : "dma_result=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    // 전문 준비 — 명세 register 의 requestData { isurCd } 는 dma_detail.isurCd 로 함께 보낸다
    // (executeDynamic 은 requestData 를 주면 ref 를 무시한다 — §5 차이 #4).
    // TODO: 서버가 isurCd 를 본문 외로 따로 받아야 하는지 확인 (§10 #1)
    // 원본 LIST_BZ_TP_CD=121 은 secugrpId(SW) 로 서버가 정한다(명세 주석, §10 #11).
    dma_detail.set("isurCd", scwin.isurCd);
    dma_detail.set("secugrpId", scwin.secugrpId);
    dma_detail.set("nparvalstkYn", (dma_detail.get("nparvalstkYn") === "Y") ? "Y" : "");    // 원본 체크 Y / 해제 ""

    dma_result.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!await scwin.checkResult(result, jobNm)) return;

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", jobNm));

    // 성공한 뒤에만 업무처리번호를 확정한다 — 실패한 신규 번호가 남지 않게(§8 #7).
    if (trJob === "I") {
        scwin.bzProcsNo = dma_result.get("bzProcsNo") || dma_detail.get("bzProcsNo");
    }

    // 다시 조회한 뒤 수정 모드(원본 OnSuccess 의 setUpdateStatus) — 부모 재조회는 팝업이 닫힌 뒤 부모가 한다(§8 #12).
    if (!await scwin.selectDetail()) return;
    $c.util.setButtonState("grpBtnBox", "update", scwin.BTN_MAP);
    scwin.setPrintVisible();
};

/**
 * @method
 * @name scwin.removeTrs
 * @author Inswave
 * @date 2026. 10. 27
 * @description 삭제. dma_detail 을 ref 로 보내고, 성공하면 팝업을 닫는다 — 부모는 await 가 끝나면 목록을 다시 조회한다.
 * (원본 fn_trs(TRS_IDX_DELETE) + OnSuccess 의 TR_JOB "D" 분기 — §5.7)
 * @returns
 * @hidden N
 */
scwin.removeTrs = async function () {
    const sbmOptions = {
        id : "sbm_removeTrs",
        method : "post",
        action : "/api/listing/lstproc/warrant/listing/remove",
        ref : "dma_detail",
        target : "dma_result=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    dma_result.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!await scwin.checkResult(result, "삭제")) return;

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    $c.win.closePopup();
};

/**
 * @method
 * @name scwin.selectPrint
 * @author Inswave
 * @date 2026. 10. 27
 * @description 인쇄 자료 조회. (원본 fn_report_read_sync(vBzProcsNo, DIV_IDX_NEW_ISS_SWR_REPORT) — §5.8)
 * @returns {Promise<Boolean>} 조회 성공 여부 — 실패면 인쇄를 멈춘다
 * @hidden N
 */
scwin.selectPrint = async function () {
    const sbmOptions = {
        id : "sbm_selectPrint",
        method : "get",
        action : "/api/listing/lstproc/warrant/listing/print",
        target : "dma_print=body",
        isProcessMsg : false
    };

    dma_print.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo : dma_detail.get("bzProcsNo") });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    return result.responseJSON?.success === true;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.initNewForm
 * @author Inswave
 * @date 2026. 10. 27
 * @description 빈 상세 준비(신규·접수 공통). 상장방식은 신주상장(1)으로 둔다. 통신 없음. (원본 fn_SetHeader + fn_initItem — §6.4, §5.9)
 * @returns
 * @hidden N
 */
scwin.initNewForm = function () {
    dma_detail.setEmptyValue();
    dma_view.setEmptyValue();
    scwin.detailRow = {};

    dma_detail.set("listMethdTpCd", $c.lc.glb.LIST_METHD_TP_CD_1);
    dma_detail.set("isurCd", scwin.isurCd);
    dma_detail.set("secugrpId", scwin.secugrpId);
};

/**
 * @method
 * @name scwin.applyRecv
 * @author Inswave
 * @date 2026. 10. 27
 * @description 접수 내역 반영. 부모가 넘긴 접수 행 값을 상세에 채운다 — 코스닥이면 상장일도. (원본 fn_recv_read_sync — §6.3)
 * @param {Object} recv 접수 목록 선택 행 (TODO: 키 이름은 부모 접수 목록 TO-BE 정의를 따른다 — §10 #6)
 * @returns
 * @hidden N
 */
scwin.applyRecv = function (recv) {
    if (!recv) return;

    ["bzProcsNo", "acptNo", "isuDd", "listShrs", "exerPrc", "isuShrs", "totIsuPrc", "exerStrtDd", "exerEndDd", "remk"]
        .forEach(key => dma_detail.set(key, recv[key] ?? ""));
    // 업무처리번호·접수번호는 파라미터(scwin.bzProcsNo·acptNo) 하나를 기준으로 둔다 — recv 키 이름이 달라도
    // 삭제·인쇄·등록에 빈 bzProcsNo 가 가지 않게 (§10 #6)
    dma_detail.set("bzProcsNo", scwin.bzProcsNo);
    dma_detail.set("acptNo", scwin.acptNo);
    dma_detail.set("nparvalstkYn", (recv.nparvalstkYn === "Y") ? "Y" : "");

    if (scwin.mktTpCd === "2") {
        dma_detail.set("listDd", recv.listDd ?? "");
    }

    dma_detail.set("listMethdTpCd", $c.lc.glb.LIST_METHD_TP_CD_1);
};

/**
 * @method
 * @name scwin.setDetailFromList
 * @author Inswave
 * @date 2026. 10. 27
 * @description 조회 목록(dlt_list)에서 업무처리번호 행을 찾아 dma_detail(같은 이름 키)·dma_view 에 옮기고, 행 전체는 scwin.detailRow 에 둔다. (§5.1 후처리)
 * isuRnd 는 dlt_list 에서 number, dma_detail 에서 text 라 문자열로 맞춘다(§10 #5).
 * @returns {Boolean} 해당 행을 찾았으면 true
 * @hidden N
 */
scwin.setDetailFromList = function () {
    const row = dlt_list.getAllJSON().find(item => String(item.bzProcsNo ?? "") === scwin.bzProcsNo);
    if (!row) {
        scwin.detailRow = {};
        return false;
    }
    scwin.detailRow = { ...row };    // 공시안내문 mst 용 원본 행 전체 (§6.5)

    const detail = {};
    Object.keys(dma_detail.getJSON()).forEach(key => {
        if (key in row) detail[key] = row[key] ?? "";
    });
    detail.isuRnd = String(row.isuRnd ?? "");
    detail.secugrpId = scwin.secugrpId;

    dma_detail.setEmptyValue();
    dma_detail.setJSON(detail);

    dma_view.set("tarstkIsuNm", row.tarstkIsuNm ?? "");
    dma_view.set("disclsYn", row.disclsYn ?? "");
    return true;
};

/**
 * @method
 * @name scwin.applyButtonState
 * @author Inswave
 * @date 2026. 10. 27
 * @description 조회 뒤 버튼 상태. 신규·업무처리번호 없는 접수는 insert, 그 밖은 상장일이 지나면 error(모두 잠김)이되
 * 공시되지 않은 건은 update 로 덮는다. (원본 dts_Isu OnLoadCompleted — §6.11)
 * @returns
 * @hidden N
 */
scwin.applyButtonState = function () {
    if (scwin.openTyp === "N" || (scwin.openTyp === "R" && $c.util.isEmpty(scwin.bzProcsNo))) {
        $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
        return;
    }
    $c.stf.setButtonSetWithDate(edt_LIST_DD, false, "grpBtnBox", scwin.BTN_MAP);                // 상장일 ≤ 오늘 → error
    $c.stf.setButtonSetWithDate2(dma_view.get("disclsYn"), "grpBtnBox", scwin.BTN_MAP);       // 미공시 → update 로 덮어씀
};

/**
 * @method
 * @name scwin.setBtnRecvIsuDel
 * @author Inswave
 * @date 2026. 10. 27
 * @description [신청종목삭제] 활성 — 접수(R)이고 업무처리번호가 있을 때만. (원본 fn_setBtnRecvIsuDel — §6.12)
 * @returns
 * @hidden N
 */
scwin.setBtnRecvIsuDel = function () {
    const enable = (scwin.openTyp === "R") && !$c.util.isEmpty(scwin.bzProcsNo);
    btn_RecvIsuDel.setDisabled(!enable);
};

/**
 * @method
 * @name scwin.setPrintVisible
 * @author Inswave
 * @date 2026. 10. 27
 * @description [인쇄]·승인일(인쇄용) 표시. 유가는 숨기고, 코스닥 등은 업무처리번호 없는 접수만 숨긴다.
 * 원본 저장 성공 처리는 btn_Print 만 토글했으나 세 요소를 함께 맞춘다(§6.10, §8 #8).
 * @returns
 * @hidden N
 */
scwin.setPrintVisible = function () {
    const hidden = (scwin.mktTpCd === "1") || (scwin.openTyp === "R" && $c.util.isEmpty(scwin.bzProcsNo));

    [btn_Print, label_26, edt_APPROV_DD].forEach(comp => {
        if (hidden) {
            comp.hide();
        } else {
            comp.show("");
        }
    });
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 27
 * @description 저장·수정 전 입력 검증. 원본 fn_CheckForm 순서를 따른다 — 필수 검사는 공통 검증(validateDataCollect)을
 * 원본 순서대로 나눠 부르고, 그 사이에 업무 검사(현재일 비교·선후·조건부 필수)와 서버 중복 확인을 둔다. (§6.1)
 * @param {String} trJob 처리구분 I: 저장, U: 수정
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
 */
scwin.validate = async function (trJob) {
    const curDate = $c.date.getServerDateTime().substring(0, 8);
    const isuCd = dma_detail.get("isuCd");

    // 1) 종목
    if ($c.util.isEmpty(isuCd)) {
        await $c.win.alert("[종목]을 선택하세요.");
        img_ISU_CD.focus();
        return false;
    }

    // 2) 종목 중복(신규상장 처리 중) — 신규 저장만
    // TODO: pcc checkDoubleInput 은 요청 키 isurCd·주식 신규상장 경로다 — 종목코드로 불러도 되는지 확인 (§5.3, §10 #4)
    if (trJob === "I" && await $c.lc.checkDoubleInput(isuCd)) return false;

    // 3) 단축코드 — 원본도 안내만 하고 계속한다(§8 #6)
    if ($c.util.isEmpty(dma_detail.get("isuSrtCd"))) {
        await $c.win.alert("[종목단축코드]항목값이  없습니다.");
    }

    // 4) 종목명 4종 · 발행일 · 상장일 필수
    // TODO: 종목명 maxlength 40/20/80/40 은 글자 수라 안내 "(한글:30자)" 등의 byte 의미와 다르다 — 길이 기준 확인 (§10 #10)
    const nameOptions = {
        validateType : "alert",
        checkType : "single",
        fields : {
            txb_ISU_KOR_NM : { required : true, name : "한글종목명" },
            txb_ISU_KOR_ABBRV : { required : true, name : "한글종목약명" },
            txb_ISU_ENG_NM : { required : true, name : "영문종목명" },
            txb_ISU_ENG_ABBRV : { required : true, name : "영문종목약명" },
            edt_ISU_DD : { required : true, format : "date", name : "발행일" },
            edt_LIST_DD : { required : true, format : "date", name : "상장일" }
        }
    };
    if (!await $c.validate.validateDataCollect(panel_Item, nameOptions)) return false;

    // 5) 상장일은 현재일 이후
    if (dma_detail.get("listDd") <= curDate) {
        await $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }

    // 6) 행사종료일 필수 · 현재일 이후 (행사시작일 필수·현재일 검사는 원본에서 주석 — 하지 않음)
    const endOptions = {
        validateType : "alert",
        checkType : "single",
        fields : {
            edt_EXER_END_DD : { required : true, format : "date", name : "행사종료일" }
        }
    };
    if (!await $c.validate.validateDataCollect(panel_Item, endOptions)) return false;

    const exerStrtDd = dma_detail.get("exerStrtDd");
    const exerEndDd = dma_detail.get("exerEndDd");
    if (exerEndDd <= curDate) {
        await $c.win.alert("[행사종료일]을 현재일이후로 입력하세요.");
        edt_EXER_END_DD.focus();
        return false;
    }

    // 7) 행사시작일 < 행사종료일 (같으면 실패, 시작일이 비면 원본처럼 건너뜀)
    if (!$c.util.isEmpty(exerStrtDd) && exerStrtDd >= exerEndDd) {
        await $c.win.alert("[행사시작일]은 [행사종료일]보다 작아야 합니다. 다시 입력해주세요");
        return false;
    }

    // 8) 상장방식 · 상장증권수량 · 발행주식수 필수
    const qtyOptions = {
        validateType : "alert",
        checkType : "single",
        fields : {
            cmb_LIST_METHD_TP_CD : { required : true, name : "상장방식" },
            edt_LIST_SHRS : { required : true, name : "상장증권수량" },
            edt_ISU_SHRS : { required : true, name : "발행주식수" }
        }
    };
    if (!await $c.validate.validateDataCollect(panel_Item, qtyOptions)) return false;

    // 9) 무액면이 아니면 행사가격 필수 — 체크박스 바인딩 값으로 판정(§8 #5)
    if (dma_detail.get("nparvalstkYn") !== "Y" && $c.util.isEmpty(dma_detail.get("exerPrc"))) {
        await $c.win.alert("[행사가격]을 입력하세요.");
        edt_EXER_PRC.focus();
        return false;
    }

    // 10) 발행가액총액 필수 — 공통 검증은 컨테이너 DOM 순서로 검사하므로(발행사유가 화면 위쪽) 원본 순서(총액 → 사유)를 지키려고 따로 부른다
    const totOptions = {
        validateType : "alert",
        checkType : "single",
        fields : {
            edt_TOT_ISU_PRC : { required : true, name : "발행가액총액" }
        }
    };
    if (!await $c.validate.validateDataCollect(panel_Item, totOptions)) return false;

    // 11) 발행사유 · 신주인수권의 내용 · 신주의 납입방법 필수
    const etcOptions = {
        validateType : "alert",
        checkType : "single",
        fields : {
            txb_ISU_RSN_CONTN : { required : true, name : "발행사유" },
            txb_SUBSRGHT_CONTN : { required : true, name : "신주인수권의 내용" },
            txb_SUBSRGHT_EXERTM_PAYMETHD_CONTN : { required : true, name : "신주의 납입방법" }
        }
    };
    if (!await $c.validate.validateDataCollect(panel_Item, etcOptions)) return false;

    // 12) 업무 중복 입력 확인
    // TODO: pcc checkBzDoubleInput 은 주식 변경상장 경로(stock/chglisting/check-double-input) — 121 업무에서도 맞는지 확인 (§5.4, §10 #4)
    // TODO: pcc 결함 (§10 #4, 배포 전 차단) — checkBzDoubleInput 은 응답에 disclsProcsDdtm 이 없으면(undefined) 중복으로 보고 false 라
    //       저장·수정이 늘 막힌다. checkDoubleInput(위 2)은 dbinputYn 이 Y/N 밖이면 undefined 로 통과한다. 둘 다 skipped 가드가 없다 — pcc 수정 요청
    return await $c.lc.checkBzDoubleInput(isuCd, dma_detail.get("listDd"), scwin.bzProcsNo, $c.lc.glb.LIST_BZ_TP_CD_121);
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 27
 * @description 종목 찾기. 발행기관의 미상장 종목(ULDSTF92016)을 골라 상세에 채운다. 취소·닫기면 아무것도 하지 않는다.
 * (원본 img_ISU_CD onclick + fn_GetParIsuCd + fn_PopFindNewIsuOfIsur — §6.2)
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    if ($c.util.isEmpty(scwin.isurCd)) {
        await $c.win.alert("[회사]를 선택하세요.");
        return;
    }

    // AS-IS arr[0] 증권그룹ID, arr[1] 발행회사코드 (arr[2] "S" 는 pcc·92016 전환본 모두 받지 않음 — §10 #9)
    const result = await $c.lc.popFindNewIsuOfIsur(scwin.secugrpId, scwin.isurCd);
    if (result?.isCloseButtonClick === true || $c.util.isEmpty(result?.isuCd)) return;    // 취소·닫기

    scwin.setIsu(result);
};

/**
 * @method
 * @name scwin.setIsu
 * @author Inswave
 * @date 2026. 10. 27
 * @description 종목선택(ULDSTF92016) 결과를 상세에 채운다. (원본 fn_SetParIsuCd — §6.2)
 * @param {Object} isu 선택 행 (TODO: 반환 키는 92016 전환본 기준 가정 — §10 #9)
 * @returns
 * @hidden N
 */
scwin.setIsu = function (isu) {
    dma_detail.set("isuCd", isu.isuCd ?? "");
    dma_detail.set("isuSrtCd", isu.isuSrtCd ?? "");
    dma_detail.set("isuKorNm", isu.isuNm ?? "");
    dma_detail.set("isuKorAbbrv", isu.isuSnm ?? "");
    dma_detail.set("isuEngNm", isu.isuEngNm ?? "");
    dma_detail.set("isuEngAbbrv", isu.isuEngSnm ?? "");
    dma_detail.set("isuRnd", String(isu.isuRnd ?? ""));
    dma_detail.set("isuDd", isu.isuDd ?? "");
    dma_detail.set("tarstkIsuCd", isu.tarstkIsuCd ?? "");
    dma_view.set("tarstkIsuNm", isu.tarstkIsuNm ?? "");
};

/**
 * @method
 * @name scwin.getNewBzProcsNo
 * @author Inswave
 * @date 2026. 10. 27
 * @description 업무처리번호를 새로 받는다. $c.stf.getNewBzProcNo 는 응답 봉투를 그대로 돌려줄 수 있어 body 를 꺼내고,
 * body 가 문자열이면 그대로, 객체면 bzProcsNo 를 문자열로 만든다. 14자리 검사는 호출부(scwin.save)가 한다. (§5.2)
 * @returns {Promise<String>} 업무처리번호 (실패면 빈 문자열)
 * @hidden N
 */
scwin.getNewBzProcsNo = async function () {
    // TODO: 채번 주체 — 명세 register 응답 bzProcsNo 로 서버 채번도 가능, 지금은 원본대로 화면 채번 (§10 #3)
    // TODO: 채번 응답 모양 미확정 — body 가 문자열인지 { bzProcsNo } 인지 확인 (§10 #3). 지금은 둘 다 받는다.
    const res = await $c.stf.getNewBzProcNo();
    const body = res?.body ?? res;
    const no = String((typeof body === "object" && body !== null) ? (body.bzProcsNo ?? "") : (body ?? ""));
    return no;
};

/**
 * @method
 * @name scwin.checkResult
 * @author Inswave
 * @date 2026. 10. 27
 * @description 저장·수정·삭제 응답 판정. 통신 실패이거나 completeYn 이 성공 값이 아니면 MSG-A002 를 안내하고 false. (§5.5~5.7)
 * @param {Object} result executeDynamic 결과
 * @param {String} jobNm 처리명 (저장·수정·삭제)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.checkResult = async function (result, jobNm) {
    // TODO: completeYn 의 성공 값("Y")은 가정 — 명세 확인 필요 (§10 #7)
    if (result.responseJSON?.success && dma_result.get("completeYn") === scwin.COMPLETE_YN_OK) return true;

    await $c.win.alert($c.stf.getMessageParam("MSG-A002", jobNm));
    return false;
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 27
 * @description 신규 저장. 검증 → 확인 → 채번(접수 건은 받은 번호) → 등록 순서 (원본 fn_save — §6.7, §1.4 업무 4)
 * 채번이 확인보다 뒤라서 취소한 건에는 번호가 소비되지 않는다.
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate(scwin.trJob)) return;

    // "[저장] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    // 접수 건(접수번호 있음)은 채번하지 않고 받은 업무처리번호를 쓴다(§8 #3).
    const bzProcsNo = $c.util.isEmpty(scwin.acptNo) ? await scwin.getNewBzProcsNo() : scwin.bzProcsNo;
    if (bzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }

    dma_detail.set("bzProcsNo", bzProcsNo);
    dma_detail.set("acptNo", scwin.acptNo);
    await scwin.saveTrs(scwin.trJob);
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 27
 * @description 수정. 검증 → 확인 → 수정 순서 (원본 fn_update — §6.8, §1.4 업무 5). 원본은 변경 여부를 확인하지 않는다.
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate(scwin.trJob)) return;

    // "[수정] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.saveTrs(scwin.trJob);
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 27
 * @description 삭제. 확인을 받은 뒤 삭제한다. 입력 검증은 하지 않는다. (원본 fn_delete — §6.9, §1.4 업무 6)
 * @returns
 * @hidden N
 */
scwin.remove = async function () {
    scwin.trJob = "D";

    // "[삭제] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.removeTrs();
};

/**
 * @method
 * @name scwin.removeRecvIsu
 * @author Inswave
 * @date 2026. 10. 27
 * @description 신청종목삭제. 접수 건만 삭제와 같은 흐름으로 지운다. (원본 fn_RecvtIsuDel — §6.9, §1.4 업무 7)
 * @returns
 * @hidden N
 */
scwin.removeRecvIsu = async function () {
    if ($c.util.isEmpty(scwin.acptNo)) {
        await $c.win.alert("발행예정내역에서 대상종목을 선택하세요");
        return;
    }
    await scwin.remove();
};

/**
 * @method
 * @name scwin.getDsclData
 * @author Inswave
 * @date 2026. 10. 27
 * @description 공시안내문작성(ULDSTF92024)에 넘길 값. 원본 fn_dscl 이 fn_GetPar 로 채우던 arr 과 데이터셋이다. (§6.5)
 * mst 는 상세 조회 원본 행(scwin.detailRow) 전체 + 화면 값이다(원본은 searchIsuIssChgList 행을 통째로 넘김).
 * 유가는 arr 3개(서식·업무처리번호·회사), 코스닥은 시장구분과 영문 마스터(원본 dts_Eng_Isu = 같은 조회 결과)를 더한다.
 * @returns {Object} 넘길 data (시장구분이 1·2 가 아니면 null)
 * @hidden N
 */
scwin.getDsclData = function () {
    // AS-IS CopyDataSet(dts_Isu, param_dts_mst) — 조회 원본 행 전체 위에 화면 입력값을 덮는다
    const mst = [{ ...scwin.detailRow, ...dma_detail.getJSON(), ...dma_view.getJSON() }];

    if (scwin.mktTpCd === "1") {
        return { formCd : scwin.DSCL_FORM_CD_KSE, bzProcsNo : scwin.bzProcsNo, isurCd : scwin.isurCd, mst : mst };
    }
    if (scwin.mktTpCd === "2") {
        return {
            formCd : scwin.DSCL_FORM_CD_KOSDAQ,     // AS-IS arr[0]
            bzProcsNo : scwin.bzProcsNo,            // AS-IS arr[1]
            isurCd : scwin.isurCd,                  // AS-IS arr[2]
            mktId : scwin.mktTpCd,                  // AS-IS arr[3]
            mst : mst,
            mstEng : mst                            // AS-IS CopyDataSet(dts_Eng_Isu, param_dts_mst_eng)
        };
    }
    return null;
};

/**
 * @method
 * @name scwin.writeDscl
 * @author Inswave
 * @date 2026. 10. 27
 * @description 공시안내문작성 팝업을 data 로 넘겨 열고 닫힐 때까지 기다린다. 돌려받는 값은 없다. (원본 fn_dscl — §6.5, 가이드 §6.5)
 * @returns
 * @hidden N
 */
scwin.writeDscl = async function () {
    if ($c.util.isEmpty(dma_detail.get("isuCd"))) {
        await $c.win.alert("[종목]을 선택하세요.");
        img_ISU_CD.focus();
        return;
    }

    const data = scwin.getDsclData();
    if (!data) {
        // TODO: 시장구분 1·2 외 처리·문구는 가정 (§8 #13, §10 #8·#14)
        await $c.win.alert("안내문을 작성할 수 없는 시장구분입니다.");
        return;
    }

    const options = {
        id : "ULDSTF92024",
        popupName : "공시안내문작성",
        width : 750,
        height : 825,
        type : "pageFramePopup"
    };

    // TODO: 경로는 가정, 92024 는 아직 getPar 계약이라 수신부 변경 필요 (§10 #8)
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92024.xml", options, data);
};

/**
 * @method
 * @name scwin.getPar
 * @author Inswave
 * @date 2026. 10. 27
 * @description [호환용 · 임시] 공시안내문작성(ULDSTF92024) 전환본은 아직 부모의 scwin.getPar 를 이름으로 불러 값을 받는다.
 * 92024 가 $c.data.getParameter() 수신으로 바뀌면 이 함수를 지운다. (§6.5, §10 #8, 가이드 §6.5 예외)
 * @param {Array} arr 92024 가 넘기는 빈 배열 — [0] 서식코드 [1] 업무처리번호 [2] 발행회사코드 [3] 시장구분(코스닥만) 을 채운다
 * @param {Object} dltIsu 92024 의 종목 dataList (원본도 넘기지 않음)
 * @param {Object} dltMst 92024 의 마스터 dataList
 * @param {Object} dlt2 92024 의 원천 자료 2 (쓰지 않음)
 * @param {Object} dlt3 92024 의 원천 자료 3 (쓰지 않음)
 * @param {Object} dlt4 92024 의 원천 자료 4 (쓰지 않음)
 * @param {Object} dltIsuEng 92024 의 영문 종목 dataList (쓰지 않음)
 * @param {Object} dltMstEng 92024 의 영문 마스터 dataList (코스닥만)
 * @returns {Number} arr 길이
 * @hidden N
 */
scwin.getPar = function (arr, dltIsu, dltMst, dlt2, dlt3, dlt4, dltIsuEng, dltMstEng) {
    const data = scwin.getDsclData();
    if (!data) return arr.length;

    arr[0] = data.formCd;
    arr[1] = data.bzProcsNo;
    arr[2] = data.isurCd;
    if (data.mktId) arr[3] = data.mktId;

    scwin.fillDataList(dltMst, data.mst);
    if (data.mstEng) scwin.fillDataList(dltMstEng, data.mstEng);

    return arr.length;
};

/**
 * @method
 * @name scwin.fillDataList
 * @author Inswave
 * @date 2026. 10. 27
 * @description 컬럼 정의가 비어 있는 다른 화면의 dataList 에 행을 채운다. setJSON 은 선언된 컬럼만 옮기므로 첫 행의 키로 컬럼을 먼저 만든다.
 * (92024 의 원천 자료 dataList 는 서식마다 컬럼이 달라 부모가 컬럼째 넘긴다 — 원본 CopyDataSet)
 * @param {Object} dataList 채울 dataList (없으면 무시)
 * @param {Array} rows 넣을 행 목록
 * @returns
 * @hidden N
 */
scwin.fillDataList = function (dataList, rows) {
    if (!dataList) return;

    Object.keys(rows[0] ?? {}).forEach(key => {
        if (dataList.getColumnIndex(key) < 0) dataList.insertColumn(key);
    });
    dataList.setJSON(rows);
};

/**
 * @method
 * @name scwin.print
 * @author Inswave
 * @date 2026. 10. 27
 * @description 증권발행내역 인쇄. 인쇄 자료를 조회해 리포트 파라미터를 만들고 PDF 미리보기 창을 연다. (원본 fn_print — §6.6)
 * 승인일은 응답 commitDd 가 아니라 승인일(인쇄용) 입력값이다(원본 그대로). 원본 doLogSave 는 삭제(§8 #14).
 * @returns
 * @hidden N
 */
scwin.print = async function () {
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        // TODO: 가정 문구 (§8 #8, §10 #14)
        await $c.win.alert("저장 후 인쇄하세요.");
        return;
    }

    if (!await scwin.selectPrint()) return;

    const rpt = dma_print.getJSON();
    const num = value => $c.num.formatNumber(value);          // AS-IS FormatNumberEx
    const date = value => $c.date.formatDate(value, "-");     // AS-IS FormatDateEx (yyyy-MM-dd)

    const userParam = [
        { uid : "COM_NM", unm : rpt.comNm },
        { uid : "ISU_INFO", unm : rpt.isuCd + " / " + rpt.isuSrtCd },
        { uid : "ISU_KOR_NM", unm : rpt.isuKorNm },
        { uid : "ISU_KOR_ABBRV", unm : rpt.isuKorAbbrv },
        { uid : "ISU_ENG_NM", unm : rpt.isuEngNm },
        { uid : "ISU_ENG_ABBRV", unm : rpt.isuEngAbbrv },
        { uid : "ISU_RSN_CONTN", unm : rpt.isuRsnContn },
        { uid : "TARSTK_ISU_NM", unm : rpt.tarstkIsuNm },
        { uid : "SUBSRGHT_EP_CONTN", unm : rpt.subsrghtEpContn },
        { uid : "LIST_SHRS", unm : num(rpt.listShrs) },
        { uid : "EXER_PRC", unm : num(rpt.exerPrc) },
        { uid : "ISU_SHRS", unm : num(rpt.isuShrs) },
        { uid : "TOT_ISU_PRC", unm : num(rpt.totIsuPrc) },
        { uid : "EXER_STRT_DD", unm : date(rpt.exerStrtDd) },
        { uid : "EXER_END_DD", unm : date(rpt.exerEndDd) },
        { uid : "COMMIT_DD", unm : date(edt_APPROV_DD.getValue()) },
        { uid : "ISU_DD", unm : date(rpt.isuDd) },
        { uid : "ISU_DD_INFO", unm : rpt.isuDd + " / 제" + rpt.isuRnd + "회" },
        { uid : "LIST_DD", unm : date(rpt.listDd) }
    ];

    // TODO: 조회(await) 뒤 window.open 이라 팝업 차단 여부를 실화면에서 확인 (§10 #12)
    $c.print.openReportPdf(scwin.REPORT_ID, userParam);
};
